package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

// file handling for COBOL READ
var taxRec TaxRec
var inputLines []string
var inputPos int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func truncateDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep only low-order integer digits that fit
	// scale is number of fractional digits
	if intDigits <= 0 {
		return val
	}
	// work with absolute value, restore sign at end
	sign := val.Sign()
	abs := val.Abs()
	// separate integer and fractional part using scale
	// ensure val has at most scale fractional digits (truncate already)
	// Get integer part = floor(abs)
	intPart := abs.Truncate(0)
	frac := abs.Sub(intPart)
	// count digits of intPart
	// if intPart fits, return original
	// else modulo 10^intDigits
	tenPow := decimal.New(1, int32(intDigits)) // 10^intDigits
	// 10^intDigits as decimal
	// Use DivMod? simpler: if intPart >= tenPow then intPart = intPart.Mod(tenPow)
	if intPart.GreaterThanOrEqual(tenPow) {
		intPart = intPart.Mod(tenPow)
		newAbs := intPart.Add(frac)
		if sign < 0 {
			newAbs = newAbs.Neg()
		}
		// ensure scale truncation (keep exact scale)
		return newAbs.Truncate(scale)
	}
	return val
}

func storeTax(val decimal.Decimal) {
	// PIC 9(7)V99 => 7 int digits, scale 2, rounded already
	v := val.Round(2)
	v = truncateDecimal(v, 7, 2)
	WsTax = v
}

func storeNet(val decimal.Decimal) {
	// without ROUNDED => truncate
	v := val.Truncate(2)
	v = truncateDecimal(v, 7, 2)
	WsNet = v
}

func storeTotal(val decimal.Decimal) {
	v := val.Truncate(2)
	v = truncateDecimal(v, 9, 2)
	WsTotalTax = v
}

func formatEdited(val decimal.Decimal, pic string) string {
	// pic like "ZZZ,ZZ9.99" or "ZZ,ZZZ,ZZ9.99"
	// split at '.'
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	scale := len(fracPic)
	// count placeholder digits in intPic (Z and 9)
	capacity := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			capacity++
		}
	}
	// prepare padded integer and fractional strings
	abs := val.Abs().Truncate(int32(scale))
	// StringFixed gives exactly scale digits after decimal
	var s string
	if scale > 0 {
		s = abs.StringFixed(int32(scale))
	} else {
		s = abs.Truncate(0).StringFixed(0)
	}
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// pad fracStr to scale
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		}
	} else {
		intStr = s
		fracStr = ""
	}
	// handle overflow: keep low-order digits
	if len(intStr) > capacity {
		intStr = intStr[len(intStr)-capacity:]
	}
	// left pad with zeros to capacity
	if len(intStr) < capacity {
		intStr = strings.Repeat("0", capacity-len(intStr)) + intStr
	}
	paddedInt := intStr

	// build integer part output
	outInt := make([]byte, len(intPic))
	pIdx := 0
	suppressed := true
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			digit := paddedInt[pIdx]
			pIdx++
			if suppressed {
				if ch == '9' {
					outInt[i] = digit
					suppressed = false
				} else { // Z
					if digit != '0' {
						outInt[i] = digit
						suppressed = false
					} else {
						outInt[i] = ' '
						// suppressed stays true
					}
				}
			} else {
				outInt[i] = digit
			}
		} else {
			outInt[i] = byte(ch)
		}
	}
	var result string
	if scale > 0 {
		result = string(outInt) + "." + fracStr
	} else {
		result = string(outInt)
	}
	// ensure exact length (pic length)
	// pic length includes dot
	if len(result) != len(pic) {
		// pad/truncate (should not happen)
		if len(result) < len(pic) {
			result = strings.Repeat(" ", len(pic)-len(result)) + result
		}
	}
	return result
}

func formatCount(v int64) string {
	// PIC 9(3) zero padded, high-order truncated
	// v already truncated to 3 digits via modulo, but ensure
	if v < 0 {
		v = -v
	}
	v = v % 1000
	return fmt.Sprintf("%03d", v)
}

// paragraph functions

func ReadPara() {
	if inputPos >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	// pad to 13 with spaces if needed
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	}
	if len(line) > 13 {
		line = line[:13]
	}
	trId := line[0:5]
	trIncomeRaw := line[5 : 5+8]
	// parse decimal: digits only, implied 2 decimals
	trimmed := strings.TrimSpace(trIncomeRaw)
	var dec decimal.Decimal
	if trimmed == "" {
		dec = decimal.NewFromInt(0)
	} else {
		// trimmed should be digits, may contain spaces inside -> remove spaces
		clean := strings.ReplaceAll(trIncomeRaw, " ", "0")
		// Actually spaces inside should be treated as 0? Use trimmed digits.
		// Use clean: keep only digits
		digits := ""
		for _, c := range clean {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			dec = decimal.NewFromInt(0)
		} else {
			// digits represents value *100
			// Use NewFromString with shift
			// parse as integer
			i, _ := decimal.NewFromString(digits)
			dec = i.Shift(-2)
		}
	}
	taxRec.TrId = trId
	taxRec.TrIncome = dec
	inputPos++
}

func ProcessPara() {
	// IF TR-INCOME <= 10000.00 COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
	// ELSE IF <=40000 ...
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	oneThousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)

	var computed decimal.Decimal
	if taxRec.TrIncome.LessThanOrEqual(tenThousand) {
		computed = taxRec.TrIncome.Mul(rate10)
		computed = computed.Round(2)
		storeTax(computed)
	} else {
		if taxRec.TrIncome.LessThanOrEqual(fortyThousand) {
			diff := taxRec.TrIncome.Sub(tenThousand)
			computed = oneThousand.Add(diff.Mul(rate20))
			computed = computed.Round(2)
			storeTax(computed)
		} else {
			diff := taxRec.TrIncome.Sub(fortyThousand)
			computed = sevenThousand.Add(diff.Mul(rate30))
			computed = computed.Round(2)
			storeTax(computed)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	netVal := taxRec.TrIncome.Sub(WsTax)
	storeNet(netVal)

	// ADD WS-TAX TO WS-TOTAL-TAX
	newTotal := WsTotalTax.Add(WsTax)
	storeTotal(newTotal)

	// ADD 1 TO WS-COUNT (with overflow truncation)
	WsCount = WsCount + 1
	// truncate to 3 digits (low-order)
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}

	// MOVE to edited
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	PerformReadPara()
}

func PerformReadPara() { ReadPara() }

func MainPara() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	PerformReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE TAX-FILE (implicit)
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MainPara()
}
